"""The self-contained launcher preprocess/run_preprocess.bat (generated by
preprocess/build_launcher.py) carries everything the pipeline imports, and the committed
copy is the current pipeline:

  * every module of the repository an embedded script imports (or loads by file name)
    is embedded too — format5.py, imported by steps 2-4, lives at the repository root;
  * the committed .bat announces run_preprocess.__version__ and each of its blocks
    decodes to the current source (line endings aside), in the order the .bat extracts
    them;
  * a generation fills every placeholder of the template.

When this fails after a pipeline edit: python preprocess/build_launcher.py

Run: python tests/test_build_launcher.py
"""
import ast
import base64
import importlib.util
import re
import shutil
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PRE = ROOT / "preprocess"
BAT = PRE / "run_preprocess.bat"


def _load_builder():
    spec = importlib.util.spec_from_file_location("lumen_build_launcher_test", str(PRE / "build_launcher.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


BL = _load_builder()


def _source(name: str) -> Path:
    if name == BL.DOWNLOAD_TOOL:
        return ROOT / "tools" / name
    if name in BL.SHARED_MODULES:
        return ROOT / name
    return PRE / name


def _embedded_order() -> list:
    return list(BL.SCRIPTS) + [BL.DOWNLOAD_TOOL] + list(BL.SHARED_MODULES)


def _local_imports(path: Path) -> set:
    """Modules of the repository (preprocess/ or the root) a script imports, plus the
    pipeline files it loads by name (load_step / run_step / spec_from_file_location)."""
    text = path.read_text(encoding="utf-8")
    names = set()
    for node in ast.walk(ast.parse(text)):
        if isinstance(node, ast.Import):
            names.update(alias.name.split(".")[0] for alias in node.names)
        elif isinstance(node, ast.ImportFrom) and node.module and not node.level:
            names.add(node.module.split(".")[0])
    out = {f"{n}.py" for n in names if (PRE / f"{n}.py").is_file() or (ROOT / f"{n}.py").is_file()}
    out.update(m for m in re.findall(r'(?:load_step|run_step)\(\s*"([^"]+\.py)"', text))
    return out


def _blocks(text: str) -> dict:
    blocks = {}
    for line in text.splitlines():
        m = re.match(r"^#(\d+)#(.*)$", line)
        if m:
            blocks.setdefault(int(m.group(1)), []).append(m.group(2))
    return {k: base64.b64decode("".join(v)) for k, v in blocks.items()}


def _norm(data: bytes) -> bytes:
    return data.replace(b"\r\n", b"\n")


class LauncherContents(unittest.TestCase):
    def test_every_imported_pipeline_module_is_embedded(self):
        embedded = set(_embedded_order())
        self.assertIn("format5.py", embedded)
        for name in BL.SCRIPTS + list(BL.SHARED_MODULES):
            for dep in _local_imports(_source(name)):
                if dep == BL.DOWNLOAD_TOOL:
                    continue
                self.assertIn(dep, embedded, f"{name} imports {dep}, which the launcher does not embed")

    def test_committed_launcher_is_current(self):
        if not BAT.is_file():
            self.fail(f"{BAT} missing: python preprocess/build_launcher.py")
        text = BAT.read_text(encoding="ascii")
        m = re.search(r'^set "PP_VERSION=([^"]+)"', text, re.M)
        self.assertIsNotNone(m)
        self.assertEqual(m.group(1), BL.read_pp_version(),
                         "run_preprocess.bat is stale: python preprocess/build_launcher.py")
        self.assertIn(f'set "SHARED_MODULES={" ".join(BL.SHARED_MODULES)}"', text)
        headers = re.findall(r"^:: ---- \[(\d+)\] (\S+) ", text, re.M)
        self.assertEqual([(int(i), n) for i, n in headers], list(enumerate(_embedded_order())))
        blocks = _blocks(text)
        for index, name in enumerate(_embedded_order()):
            self.assertEqual(_norm(blocks[index]), _norm(_source(name).read_bytes()),
                             f"block {index} ({name}) of run_preprocess.bat differs from the source: "
                             f"python preprocess/build_launcher.py")

    def test_generation_fills_every_placeholder(self):
        tmp = Path(tempfile.mkdtemp(prefix="lumen-launcher-"))
        saved = BL.OUTPUT
        try:
            BL.OUTPUT = tmp / "run_preprocess.bat"
            BL.main()
            text = BL.OUTPUT.read_text(encoding="ascii")
        finally:
            BL.OUTPUT = saved
            shutil.rmtree(tmp, ignore_errors=True)
        self.assertNotIn("@@@", text)
        self.assertIn(f'set "SHARED_INDEX={len(BL.SCRIPTS) + 1}"', text)
        self.assertIn(f"call :extract {len(BL.SCRIPTS)} ", text)
        blocks = _blocks(text)
        self.assertEqual(sorted(blocks), list(range(len(_embedded_order()))))
        self.assertEqual(_norm(blocks[len(BL.SCRIPTS) + 1]), _norm((ROOT / "format5.py").read_bytes()))


if __name__ == "__main__":
    unittest.main(verbosity=2)
